    cancelNoteTool();closeCommandPalette();project=emptyProject();project.bpm=120;currentFile=File();selectedTrack=7;selectedNotes.clear();selectedNote=-1;undoStack.clear();redoStack.clear();project.patterns[0].length=4;lane()={{0,.25,60,.8f}};project.tracks[7].volume=.41f;project.tracks[7].pan=.2f;publish();auto original=projectToJson(project);auto sourceLane=lane();
    check(applySynthPreset(factorySynthPresets()[6],7)&&isSynth(project.tracks[7].instrument)&&activePane==synthPane,"factory sound opens its dedicated generator editor");check(lane()==sourceLane&&project.patterns[0].length==4&&project.tracks[7].volume==.41f&&project.tracks[7].pan==.2f&&undoStack.size()==1,"sound recall preserves notes, user's step length and mixer levels in one undo");perform(undoAction);check(JSON::toString(projectToJson(project))==JSON::toString(original),"Undo restores complete previous instrument and pattern length");perform(redoAction);check(project.tracks[7].instrument==Instrument::analog,"Redo restores factory sound");
