    selectedTrack=7;showPane(rackPane);perform(instrumentSelect,(int)Instrument::analog);check(activePane==synthPane&&project.tracks[7].soundName.isEmpty(),"Browser instrument choice opens the synth editor with a truthful custom-sound label");
    auto beforeAdd=(int)project.tracks.size();perform(addChannel,(int)Instrument::fm);check((int)project.tracks.size()==beforeAdd+1&&project.tracks[(size_t)selectedTrack].instrument==Instrument::fm&&activePane==synthPane,"ADD Pulse FM creates a source channel and opens its generator editor");perform(undoAction);
    selectedTrack=7;showPane(synthPane);perform(synthPresets);auto* menu=Component::getCurrentlyModalComponent();check(menu!=nullptr,"factory sound library opens a native categorized menu");PopupMenu::dismissAllActiveMenus();
